import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"13、【同人】 离下乾上","description":"温公易说 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"温公易说 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/wengong/014.md","filePath":"zh/classics/wengong/014.md"}'),n={name:"zh/classics/wengong/014.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><h3 id="彖曰-同人-柔得位得中而应乎干-曰同人。同人曰同人于野-亨利涉大川-干行也。文明以健-中正而应-君子正也。惟君子为能通天下之志。" tabindex="-1">彖曰：同人，柔得位得中而应乎干，曰同人。同人曰同人于野，亨利涉大川，干行也。文明以健，中正而应，君子正也。惟君子为能通天下之志。 <a class="header-anchor" href="#彖曰-同人-柔得位得中而应乎干-曰同人。同人曰同人于野-亨利涉大川-干行也。文明以健-中正而应-君子正也。惟君子为能通天下之志。" aria-label="Permalink to “彖曰：同人，柔得位得中而应乎干，曰同人。同人曰同人于野，亨利涉大川，干行也。文明以健，中正而应，君子正也。惟君子为能通天下之志。”">​</a></h3><p>同人者，何？同于人之谓也。君子乐与人同，小人乐与人异。与人同者，人亦同之；与人异者，人亦异之。同则相爱，异则相恶。爱则相利，恶则相害。相利则交安，相害则交危。利害安危之端，在于同人，不可不察也。何谓君子乐与人同？请借鲁事以言之。夫季孟异室而皆出于桓，鲁卫异国而皆出于姬，姬姜异姓而皆为中国，夷夏异俗而皆列于此。君子之乐与人同也，是以近者悦，远者来。同人之利，岂不大哉！何谓小人乐与人异？小人曰：季孟异室也，吾何与哉？又曰：彼此异民也，吾何与哉？又曰：尔汝异身也，吾何与哉？此乐与人异也，是以民有灾而君弗恤，父有疾而子弗忧，兄有祸而弟弗救也。异之为害，岂不大哉！《诗》曰：自西自东，自南自北，无思不服，同之至也。又曰：翕翕訿訿，亦孔之哀。又曰：噂背憎职，竞由人异之至也。然则同而已矣，其曰同人者，何？同之道极于人也，草木禽兽不可同也。同人于野，亨利涉大川，利君子贞，何也？曰：野则言其远也，君子同其远，小人同其近。远故无不同也，近故迭相攻也。迭相攻非同人之道也。然则圣人其有私乎？曰：有。圣人之私，大众人之私。小圣人者，以天下为私者也。艺谷树蔬而食之，犕牛乘马而畜使之，皆所以役物而养人也。所私不亦大乎？夫惟圣人为能爱其身，爱其身故爱其亲，爱其亲故爱其国，爱其国故爱其道。道者，所以保天下而兼利之也。未有危人之亲而人不危其亲者也，害人之身而人不害其身者也。天下交害之而身不亡者，未之有也。然则危人适所以自危，害人适所以自害也。乌在其能私哉？夫君子小人，其为爱身一也。君子之爱身也远，小人之爱身也近。远故大，近故小。小者非他也，智不及也是。故识其大者为大人，识其小者为小人。非其志之异也，识之蔽也。君子同于正，故其同大；小人同于邪，故其同小。邪正者，小大之分也。何谓君子能通天下之志？天下之志莫不欲利而恶害，欲安而恶危，欲治而恶乱。君子能安之利之治之，使天下犹一人也。此之谓能通天下之志。</p><h3 id="象曰-天与火同人-君子以类族辨物。" tabindex="-1">象曰：天与火同人，君子以类族辨物。 <a class="header-anchor" href="#象曰-天与火同人-君子以类族辨物。" aria-label="Permalink to “象曰：天与火同人，君子以类族辨物。”">​</a></h3><h3 id="初九-同人于门-无咎-象曰-出门同人-又谁咎也。" tabindex="-1">初九：同人于门，无咎 象曰：出门同人，又谁咎也。 <a class="header-anchor" href="#初九-同人于门-无咎-象曰-出门同人-又谁咎也。" aria-label="Permalink to “初九：同人于门，无咎 象曰：出门同人，又谁咎也。”">​</a></h3><p>初者，动之始也。夫向于左者必背于右，附于前者必离于后。故同者必有所异也。初九出门同人，无咎，言未有系也。</p><h3 id="六二-同人于宗-吝-象曰-同人于宗-吝道也。" tabindex="-1">六二：同人于宗，吝 象曰：同人于宗，吝道也。 <a class="header-anchor" href="#六二-同人于宗-吝-象曰-同人于宗-吝道也。" aria-label="Permalink to “六二：同人于宗，吝 象曰：同人于宗，吝道也。”">​</a></h3><p>宗类也。类之中又有类焉。同其类者，所同狭也，故吝。</p><h3 id="九三-伏戎于莽-升其高陵-三岁不兴-象曰-伏戎于莽-敌刚也。三岁不兴-安行也。" tabindex="-1">九三：伏戎于莽，升其高陵，三岁不兴 象曰：伏戎于莽，敌刚也。三岁不兴，安行也。 <a class="header-anchor" href="#九三-伏戎于莽-升其高陵-三岁不兴-象曰-伏戎于莽-敌刚也。三岁不兴-安行也。" aria-label="Permalink to “九三：伏戎于莽，升其高陵，三岁不兴 象曰：伏戎于莽，敌刚也。三岁不兴，安行也。”">​</a></h3><h3 id="九四-乘其墉-弗克攻-吉-象曰-乘其墉-义弗克也。其吉-则困而反则也。" tabindex="-1">九四：乘其墉，弗克攻，吉 象曰：乘其墉，义弗克也。其吉，则困而反则也。 <a class="header-anchor" href="#九四-乘其墉-弗克攻-吉-象曰-乘其墉-义弗克也。其吉-则困而反则也。" aria-label="Permalink to “九四：乘其墉，弗克攻，吉 象曰：乘其墉，义弗克也。其吉，则困而反则也。”">​</a></h3><p>九三伏戎于莽，九四：乘其墉，弗克攻，吉。何也？三四者，上下之际，同异之分也。故迭争而交不胜也。伏戎于莽者，下袭上；乘其墉者，上陵下。上可变，下不可变，逆顺之势也。</p><h3 id="九五-同人先号咷而后笑-大师克相遇-象曰-同人之先-以中直也。大师相遇-言相克也。" tabindex="-1">九五：同人先号咷而后笑，大师克相遇 象曰：同人之先，以中直也。大师相遇，言相克也。 <a class="header-anchor" href="#九五-同人先号咷而后笑-大师克相遇-象曰-同人之先-以中直也。大师相遇-言相克也。" aria-label="Permalink to “九五：同人先号咷而后笑，大师克相遇 象曰：同人之先，以中直也。大师相遇，言相克也。”">​</a></h3><p>九五君也，以中正而施同人者也。夫君子好同，小人好异，德之未充，信之未孚。近者不服，远者不怀，故号咷也。中则不阿，正则不私。不阿不私，天下归之。始于忧勤，终于逸乐，故后笑也。同者之与多，异者之与寡。寡不足以胜众，故圣人在上，天下大同者，化于众也。子曰：君子之道，或出或处，或默或语，迹之异也。二人同心，其利断金。言道之同也。二人言其寡也，金物之难断者也。二人同心，犹可以断，况于众乎？同心之言，其臭如兰。兰，芬物也。言犹如是，况其道乎？美之至也。</p><h3 id="上九-同人于郊-无悔-象曰-同人于郊-志未得也。" tabindex="-1">上九：同人于郊，无悔 象曰：同人于郊，志未得也。 <a class="header-anchor" href="#上九-同人于郊-无悔-象曰-同人于郊-志未得也。" aria-label="Permalink to “上九：同人于郊，无悔 象曰：同人于郊，志未得也。”">​</a></h3><p>郊者，外也。不同于人而亦不异于人，是以无悔，而志未得也。</p><p>附</p><p>按序卦之义，否者物不相交之卦也。不相交则异，异则争，争则穷，故受之以同人。同人者，所以通之也。物通则大有矣。</p>',17)])])}const b=e(n,[["render",l]]);export{_ as __pageData,b as default};
